#[test]
fn load_is_read_parse_then_resolve() {
    let tmp = tempfile::tempdir().expect("tempdir");
    let content = format!(
        "{RELEASE_HEAD}forge-repository = \"orin-dx/callisto\"\n{ARTIFACT}\n[cascade]\nmode = \"always\"\n\n[registries.corp]\nkind = \"cargo\"\nurl = \"https://corp.example/index\"\n\n[[package]]\nmatch = \"cargo/demo\"\npublish-to = [\"crates-io\"]\n"
    );
    fs::write(tmp.path().join("callisto.toml"), &content).expect("write callisto.toml");
    let loaded = load(tmp.path()).unwrap();
    let resolved = resolve(tmp.path(), toml::from_str::<RawConfig>(&content).unwrap()).unwrap();
    assert_eq!(format!("{loaded:?}"), format!("{resolved:?}"));
    assert_eq!(loaded.cascade.mode, CascadeMode::Always);
    assert_eq!(forge(&loaded).as_deref(), Some("orin-dx/callisto"));
}

fn bare_resolve(body: &str) -> ResolvedConfig {
    let raw = toml::from_str::<RawConfig>(body).expect("parse");
    resolve(Path::new("/workspace"), raw).expect("resolve")
}

